<div class="page-heading split"><div><p class="eyebrow"><a href="<?= e(url('campaigns')) ?>">Campaigns</a> / Status</p><h1><?= e($campaign['name']) ?></h1><p class="muted">Created <?= e(date('M j, Y H:i',strtotime($campaign['created_at']))) ?> UTC · <?= (int)$campaign['recipient_count'] ?> recipients × <?= (int)$campaign['part_count'] ?> parts</p></div><?php if(in_array($campaign['status'],['queued','processing'],true)): ?><form method="post" action="<?= e(url('campaigns/cancel')) ?>" data-confirm="Cancel all pending message parts? Parts already sent to the provider cannot be recalled."><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$campaign['id'] ?>"><button class="button button-danger" type="submit">Cancel pending</button></form><?php endif; ?></div>
<div class="stats-grid compact-stats"><?php foreach(['delivered'=>'Delivered','accepted'=>'Provider accepted','sending'=>'Sending','queued'=>'Queued','retry_wait'=>'Retry waiting','failed'=>'Failed','cancelled'=>'Cancelled'] as $key=>$label): ?><article class="stat-card"><p class="stat-label"><?= e($label) ?></p><p class="stat-value"><?= (int)($progress[$key]??0) ?></p></article><?php endforeach; ?></div>
<div class="notice notice-info"><strong>Status meaning:</strong> <em>Provider accepted</em> means the delivery platform received the request; it is not confirmed WhatsApp delivery. Only a verified provider callback marks a message part as delivered or failed. Quota is reserved per recipient × part; pending cancellations and permanent failures release unused quota once, and retries never consume it twice.</div>
<section class="panel section-block"><h2>Recipient and part status</h2><?php if(!$recipients): ?><div class="empty-card"><h3>No eligible recipients</h3><p>No one in this campaign passed suppression, consent and eligibility checks.</p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Recipient</th><th>Phone</th><th>Part</th><th>Status</th><th>Detail / action</th><th>Updated</th></tr></thead><tbody><?php foreach($recipients as $r): ?><tr><td><?= e($r['display_name']?:'Unnamed') ?></td><td class="mono"><?= e($r['phone_e164']) ?></td><td><?= (int)$r['sequence_no'] ?> (<?= e($r['part_type']?:'—') ?>)</td><td><span class="badge badge-<?= e($r['job_status']?:$r['status']) ?>"><?= e(str_replace('_',' ',ucfirst($r['job_status']?:$r['status']))) ?></span></td><td class="muted small"><?= e($r['last_error']?:$r['failure_reason']?:'—') ?><?php if($r['job_id']&&in_array($r['job_status'],['queued','retry_wait'],true)): ?><form method="post" action="<?= e(url('campaigns/job-cancel')) ?>" class="inline"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['job_id'] ?>"><input type="hidden" name="campaign_id" value="<?= (int)$campaign['id'] ?>"><button type="submit" class="link-button danger">Cancel part</button></form><?php elseif($r['job_id']&&$r['job_status']==='failed'): ?><form method="post" action="<?= e(url('campaigns/job-retry')) ?>" class="inline"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['job_id'] ?>"><button type="submit" class="link-button">Retry part</button></form><?php endif; ?></td><td class="muted small"><?= e(date('M j H:i',strtotime($r['updated_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<p class="muted small">This page does not update automatically. Refresh to see the latest worker and provider statuses.</p>
